theorem pullback_isFreeMod {X Y : Scheme.{u}} (p : X ⟶ Y) {M : Y.Modules}
    (h : IsFreeMod M) : IsFreeMod ((Scheme.Modules.pullback p).obj M) :=
  External.pullback_isFreeMod p h
